const mongoose = require("mongoose");

// 1. Define what an Interview record looks like in our database
const interviewSchema = new mongoose.Schema({
    // Which user took this interview?
    user: {
        type: mongoose.Schema.Types.ObjectId,
        required: true,
        ref: 'User'
    },
    // The list of 10 MCQ questions generated by the AI
    questions: [{
        question: { type: String, required: true },
        options: [{ type: String }],
        correctOption: { type: Number },
        explanation: { type: String }
    }],
    // The candidate's answers and correctness
    qaList: [{
        question: String,
        selectedOption: Number,
        isCorrect: Boolean
    }],
    // The final score out of 100
    overallScore: {
        type: Number,
        default: 0
    },
    // Boolean to check if the interview is finished
    isCompleted: {
        type: Boolean,
        default: false
    }
}, {
    timestamps: true
});

const Interview = mongoose.model("Interview", interviewSchema);

module.exports = Interview;
